    {
      "cell_type": "code",
      "source": [
        "# test out the vectors\n",
        "foundation_vectors = np.load('/content/drive/My Drive/H4SG (Funding Locator)/foundation_vectors.npy')\n",
        "\n",
        "def search(query_text):\n",
        "    query_vector = model.encode([query_text])[0]\n",
        "\n",
        "    from sklearn.metrics.pairwise import cosine_similarity\n",
        "    scores = cosine_similarity(query_vector.reshape(1,-1), foundation_vectors)[0]\n",
        "\n",
        "    ranked = np.argsort(scores)[::-1]\n",
        "    return [(foundations[i]['name'], scores[i]) for i in ranked[:10]]\n",
        "\n"
      ],
      "metadata": {
        "id": "qWi6t5Tao-kZ"
      },
      "execution_count": null,
      "outputs": []
    },
